svg.script:

function copyToClipboard(elementId) {
    var text = document.getElementById(elementId).textContent;
    // Decode base64 if we use it, but plain text is easier if escaped. 
    // Let's assume standard text content for now, maybe base64 decoded if needed.
    // Actually, let's use base64 to avoid escaping hell in attributes.
    var decoded = atob(text);

    navigator.clipboard.writeText(decoded).then(function() {
        console.log('Copying to clipboard was successful!');
        alert('Example copied to clipboard!');
    }, function(err) {
        console.error('Could not copy text: ', err);
        alert('Failed to copy. ' + err);
    });
}

g.title:
package StatePatterns_1EntryDoExit {
    private import ScalarValues::*;
    private import SysML::*;
    action def logStart;
    action def maintain;
    action def logEnd;
    state def Active {
       entry action : logStart;
       do action : maintain;
       exit action : logEnd;
    }
}

package StatePatterns_2CompositeState {
    private import ScalarValues::*;
    private import SysML::*;
    state def Composite {
       entry;
       state Sub1;
       state Sub2;
       transition t1
          first Sub1
          then Sub2;
    }
}

package StatePatterns_3ExhibitState {
    private import ScalarValues::*;
    private import SysML::*;
    package VehicleStates { state operating; }
    part def Vehicle {
       exhibit state opState
          references VehicleStates::operating;
    }
}

package StatePatterns_4InternalTransition {
    private import ScalarValues::*;
    private import SysML::*;
    action def tick;
    action check;
    state def Monitoring {
       state Idle;
       // Internal behavior (Self-transition)
       transition t1 first Idle accept tick do check then Idle;
    }
}
